        while($offset<$length){$n=fwrite($h,substr($raw,$offset,65536));if(!is_int($n)||$n<1)hotelFail('private_write_unconfirmed');$offset+=$n;}
        if(!fflush($h)||(function_exists('fsync')&&!fsync($h)))hotelFail('private_write_unconfirmed');
    }finally{fclose($h);}
