        ||$l['tokens_per_call']!==1052200||$l['micros_per_call']!==11000000
        ||$policy['input_token_ceiling']!==1000000||$policy['reserved_micros_minimum']!==11000000||$policy['max_source_age_seconds']!==86400)hotelFail('new_budget_or_deadline_unconfirmed');
    if(!is_array($plan['stages'])||!array_is_list($plan['stages'])||count($plan['stages'])!==4)hotelFail('four_country_plan_required');
    $seen=[];foreach(['EG','TH','VN','TR'] as $stage=>$country){
        $scopes=$plan['stages'][$stage];if(!is_array($scopes)||!array_is_list($scopes)||count($scopes)!==4)hotelFail('sixteen_scope_plan_required');
        foreach($scopes as $scope){$key=HotelServerInputs::key($scope);if(($scope['country']??null)!==$country||isset($seen[$key]))hotelFail('planned_scope_identity_unconfirmed');$seen[$key]=true;}
    }
}

/** Only the already accepted terminal CAS boundary; no manual historical ledger walk. */
function hotelBoundary(PDO $pdo,bool $enabled,string $laneOwner): array {
    $lane=hotelOne($pdo,"SELECT queue_id FROM hotel_work_lane WHERE lane_key='HOTEL'");
    if($lane===null||$lane['queue_id']!==$laneOwner)hotelFail('hotel_lane_owner_unconfirmed');
    $c=hotelOne($pdo,'SELECT campaign_id,state,enabled,stage_cursor,new_accepted,historical_accepted,bootstrap_sha256,baseline_sha256,inputs_sha256,reserved_calls,reserved_tokens,reserved_micros FROM hotel_server_campaigns WHERE campaign_id=?',[HOTEL_PREDECESSOR]);
    if($c===null||$c['state']!=='complete'||((int)$c['enabled']===1)!==$enabled||(int)$c['stage_cursor']!==4
        ||(int)$c['new_accepted']!==4||(int)$c['historical_accepted']!==19||$c['bootstrap_sha256']!==HOTEL_OLD_BOOTSTRAP
        ||$c['baseline_sha256']!==HOTEL_OLD_BASELINE||$c['inputs_sha256']!==HOTEL_PREDECESSOR_INPUTS_SHA
        ||(int)$c['reserved_calls']!==8||(int)$c['reserved_tokens']!==8417600||(int)$c['reserved_micros']!==88000000)hotelFail('predecessor_CAS');
    return $c;
}
function hotelFactMap(array $records): array {
    if(!array_is_list($records)||!$records)hotelFail('accepted_facts_unconfirmed');$map=[];
    foreach($records as $record){if(!is_array($record))hotelFail('accepted_facts_unconfirmed');$key=HotelServerInputs::key($record['scope']??[]);
        if(isset($map[$key]))hotelFail('duplicate_accepted_fact');$map[$key]=hash('sha256',HotelServerInputs::json($record));}
    ksort($map);return $map;
}
/** The core owns provenance. Check its actual new seed against independently retained fact hashes. */
function hotelSeed(PDO $pdo,array $disabled,array $package,array $plan,array $expectedCarried): array {
    $seedSha=hotelHash((string)($disabled['baseline_sha256']??''));
    $row=hotelOne($pdo,'SELECT baseline_sha256,parent_sha256,document_bytes FROM hotel_server_baselines WHERE campaign_id=? AND parent_sha256 IS NULL',[HOTEL_CAMPAIGN]);
    if($row===null||$row['parent_sha256']!==null||$row['baseline_sha256']!==$seedSha||!is_string($row['document_bytes'])
        ||strlen($row['document_bytes'])<1||strlen($row['document_bytes'])>1048576||hash('sha256',$row['document_bytes'])!==$seedSha)hotelFail('server_derived_seed_readback_unconfirmed');
    $seed=hotelJson($row['document_bytes']);hotelKeys($seed,['schema','retained_baseline_sha256','predecessor','records']);
    if(HotelServerInputs::json($seed)!==$row['document_bytes']||$seed['schema']!=='hotel-server-continuation-seed-v1'
        ||$seed['retained_baseline_sha256']!==HOTEL_RETAINED_BASELINE_SHA||!is_array($seed['predecessor'])
        ||!is_array($seed['records'])||!array_is_list($seed['records']))hotelFail('server_derived_seed_readback_unconfirmed');
    $p=$seed['predecessor'];hotelKeys($p,['campaign_id','bootstrap_sha256','baseline_sha256','inputs_sha256','receipts']);
    if($p['campaign_id']!==HOTEL_PREDECESSOR||$p['bootstrap_sha256']!==HOTEL_OLD_BOOTSTRAP||$p['baseline_sha256']!==HOTEL_OLD_BASELINE
        ||$p['inputs_sha256']!==HOTEL_PREDECESSOR_INPUTS_SHA||!is_array($p['receipts'])||!array_is_list($p['receipts'])||count($p['receipts'])!==4)hotelFail('seed_predecessor_CAS');
    foreach($p['receipts'] as $i=>$ref){hotelKeys($ref,['stage_index','receipt_sha256']);if($ref['stage_index']!==$i)hotelFail('seed_receipt_refs_unconfirmed');hotelHash($ref['receipt_sha256']);}
    $seen=[];$keys=[];
    foreach($seed['records'] as $ref){hotelKeys($ref,['semantic_key','campaign_id','stage_index','candidate_sha256','receipt_sha256','record_sha256']);
        $key=hotelHash($ref['semantic_key']);if(isset($seen[$key])||!isset($expectedCarried[$key])||$ref['record_sha256']!==$expectedCarried[$key]
            ||!is_string($ref['campaign_id'])||!preg_match('/\A[A-Za-z0-9][A-Za-z0-9_-]{0,79}\z/D',$ref['campaign_id'])
            ||$ref['campaign_id']===HOTEL_CAMPAIGN||!is_int($ref['stage_index'])||$ref['stage_index']<0||$ref['stage_index']>=10)hotelFail('carried_seed_fact_unconfirmed');
        hotelHash($ref['candidate_sha256']);hotelHash($ref['receipt_sha256']);hotelHash($ref['record_sha256']);$seen[$key]=true;$keys[]=$key;
    }
    if($keys!==array_keys($expectedCarried))hotelFail('carried_seed_fact_set_unconfirmed');
    $bootstrap=hash('sha256',HotelServerInputs::json([$package['inputs_sha256'],$plan,['continuation_seed_sha256'=>$seedSha]]));
    $new=hotelOne($pdo,'SELECT campaign_id,state,enabled,stage_cursor,new_accepted,historical_accepted,bootstrap_sha256,baseline_sha256,inputs_sha256,plan_bytes,reserved_calls,reserved_tokens,reserved_micros FROM hotel_server_campaigns WHERE campaign_id=?',[HOTEL_CAMPAIGN]);
    if(($disabled['campaign_id']??null)!==HOTEL_CAMPAIGN||($disabled['state']??null)!=='disabled'||($disabled['enabled']??null)!==false
        ||($disabled['new_accepted']??null)!==0||($disabled['stage_index']??null)!==0||($disabled['historical_accepted']??null)!==19
        ||($disabled['bootstrap_sha256']??null)!==$bootstrap||$new===null||$new['state']!=='disabled'||(int)$new['enabled']!==0
        ||(int)$new['stage_cursor']!==0||(int)$new['new_accepted']!==0||(int)$new['historical_accepted']!==19
        ||$new['bootstrap_sha256']!==$bootstrap||$new['baseline_sha256']!==$seedSha||$new['inputs_sha256']!==$package['inputs_sha256']
        ||$new['plan_bytes']!==HotelServerInputs::json($plan)||(int)$new['reserved_calls']!==0||(int)$new['reserved_tokens']!==0||(int)$new['reserved_micros']!==0)hotelFail('successor_disabled_readback_unconfirmed');
    return ['seed_sha256'=>$seedSha,'bootstrap_sha256'=>$bootstrap,'seed_bytes'=>strlen($row['document_bytes']),'carried_server_record_refs'=>count($keys)];
}
function hotelCheckedBytes(array $row,string $bytes,string $sha,int $limit): string {
    if(!is_string($row[$bytes]??null)||strlen($row[$bytes])<1||strlen($row[$bytes])>$limit
        ||!is_string($row[$sha]??null)||!hash_equals(hotelHash($row[$sha]),hash('sha256',$row[$bytes])))hotelFail('startup_stored_hash_unconfirmed');return $row[$bytes];
}
/** This observes the original attempt; it never makes, resumes or reconciles a provider call. */
function hotelObservedAttempt(array $a,string $role,array $plan,array $policy,string $inputs,string $seed,string $criteria,string $principal,array &$seen): array {
    $id=hotelHash((string)($a['attempt_id']??''));$raw=hotelCheckedBytes($a,'request_bytes','request_sha256',262144);$r=hotelJson($raw);
    if(isset($seen[$role])&&$seen[$role]!==[$id,$a['request_sha256']])hotelFail('original_startup_attempt_changed');
    if($a['campaign_id']!==HOTEL_CAMPAIGN||(int)$a['stage_index']!==0||$a['role']!==$role||$a['principal']!==$principal||$a['baseline_sha256']!==$seed
        ||HotelServerInputs::json($r)!==$raw||($r['schema']??null)!=='hotel-server-attempt-v1'||($r['attempt_id']??null)!==$id
        ||($r['campaign_id']??null)!==HOTEL_CAMPAIGN||($r['stage_index']??null)!==0||($r['role']??null)!==$role||($r['principal']??null)!==$principal
        ||($r['baseline_sha256']??null)!==$seed||($r['inputs_sha256']??null)!==$inputs||($r['criteria_sha256']??null)!==$criteria
        ||($r['model']??null)!==$policy['model']||($r['research_mode']??null)!=='assigned_retained_excerpts'
        ||HotelServerInputs::json($r['scopes']??null)!==HotelServerInputs::json($plan['stages'][0])
        ||HotelServerInputs::json($r['limits']??null)!==HotelServerInputs::json($plan['limits']))hotelFail('startup_request_lineage_unconfirmed');
    $view=$r['accepted_context']??null;if(!is_array($view))hotelFail('startup_view_unconfirmed');$viewSha=hotelHash((string)($view['view_sha256']??''));unset($view['view_sha256']);
    if(($view['schema']??null)!=='hotel-server-accepted-view-v1'||($view['baseline_sha256']??null)!==$seed||($view['retained_baseline_sha256']??null)!==HOTEL_RETAINED_BASELINE_SHA
        ||hash('sha256',HotelServerInputs::json($view))!==$viewSha)hotelFail('startup_view_unconfirmed');
    if($role==='producer'&&(($r['candidate']??null)!==null||($r['candidate_sha256']??null)!==null))hotelFail('startup_producer_candidate_unconfirmed');
    $seen[$role]=[$id,$a['request_sha256']];$proof=['attempt_id'=>$id,'role'=>$role,'state'=>$a['state'],'request_sha256'=>$a['request_sha256'],
        'principal'=>$principal,'baseline_sha256'=>$seed,'inputs_sha256'=>$inputs,'provider_call_confirmed'=>false];
    if($a['state']==='unknown'){
        if($a['result_bytes']!==null||$a['result_sha256']!==null)hotelFail('startup_unknown_result_unconfirmed');
        return ['row'=>$a,'request'=>$r,'result'=>null,'proof'=>$proof];
    }
    if($a['state']!=='succeeded')hotelFail('startup_attempt_state_unconfirmed');
    $result=hotelJson(hotelCheckedBytes($a,'result_bytes','result_sha256',2097152));
    $revision=substr($principal,strlen($policy['principals'][$role])+1);hotelHash($revision);$u=$result['provider_usage']??null;
    if(($result['attempt_id']??null)!==$id||($result['principal']??null)!==$principal||($result['baseline_sha256']??null)!==$seed||($result['inputs_sha256']??null)!==$inputs
        ||($result['provider_model']??null)!==$policy['model']||($result['profile_sha256']??null)!==$policy['profile_sha256']
        ||($result['provider_policy_sha256']??null)!==$revision||($result['budget_attestation_sha256']??null)!==HOTEL_BUDGET_SHA
        ||!is_string($result['provider_response_id']??null)||strlen($result['provider_response_id'])>256
        ||!preg_match('/\Aresp_[A-Za-z0-9_-]+\z/D',$result['provider_response_id'])||!is_array($u))hotelFail('startup_provider_result_unconfirmed');
    foreach(['input_tokens','output_tokens','total_tokens'] as $k)if(!is_int($u[$k]??null)||$u[$k]<0)hotelFail('startup_provider_usage_unconfirmed');
    if($u['total_tokens']!==$u['input_tokens']+$u['output_tokens']||$u['input_tokens']>1000000||$u['output_tokens']>2200||$u['total_tokens']>1052200
        ||($result['usage']['tokens']??null)!==$u['total_tokens']||($result['usage']['micros']??null)!==11000000
        ||($result['usage']['micros_kind']??null)!=='full_reserved_ceiling_not_provider_invoice')hotelFail('startup_provider_usage_unconfirmed');
    if(isset($result['provider_outcome'])&&($result['provider_outcome']!=='rejected'||!in_array($result['rejection_code']??null,
        ['insufficient_evidence','invalid_candidate','invalid_review','invalid_response','provider_refused','provider_incomplete'],true)))hotelFail('startup_provider_outcome_unconfirmed');
    $proof['provider_call_confirmed']=true;$proof+=['result_sha256'=>$a['result_sha256'],'provider_response_id'=>$result['provider_response_id'],
        'provider_usage'=>$u,'provider_outcome'=>$result['provider_outcome']??'answered','rejection_code'=>$result['rejection_code']??null];
    if($role==='reviewer')$proof+=['review_approved'=>$result['approved']??null,'review_evidence'=>is_string($result['evidence']??null)?substr($result['evidence'],0,4096):null];
    return ['row'=>$a,'request'=>$r,'result'=>$result,'proof'=>$proof];
}
/** One short, read-only B04 snapshot; no old campaign rows or receipts are read here. */
function hotelStartupSnapshot(PDO $pdo,array $plan,array $policy,string $inputs,string $seed,string $bootstrap,string $criteria,array $principals,array $admission,array &$seen,array &$cache): array {
    $c=hotelOne($pdo,'SELECT campaign_id,state,enabled,stage_cursor,new_accepted,bootstrap_sha256,inputs_sha256,reserved_calls,reserved_tokens,reserved_micros FROM hotel_server_campaigns WHERE campaign_id=?',[HOTEL_CAMPAIGN]);
    if($c===null||$c['bootstrap_sha256']!==$bootstrap||$c['inputs_sha256']!==$inputs||(int)$c['enabled']!==1
        ||(int)$c['stage_cursor']<0||(int)$c['stage_cursor']>4||(int)$c['new_accepted']<0||(int)$c['new_accepted']>4
        ||(int)$c['reserved_calls']<0||(int)$c['reserved_calls']>8||(int)$c['reserved_tokens']<0||(int)$c['reserved_tokens']>8417600
        ||(int)$c['reserved_micros']<0||(int)$c['reserved_micros']>88000000)hotelFail('startup_campaign_identity_unconfirmed');
    $out=['state'=>'awaiting_existing_cron','observed_at_utc'=>gmdate('c'),'campaign_state'=>$c['state'],'stage_cursor'=>(int)$c['stage_cursor'],
        'new_accepted'=>(int)$c['new_accepted'],'reserved_calls'=>(int)$c['reserved_calls'],'provider_calls_confirmed'=>0,
        'first_new_acceptance_confirmed'=>false,'automatic_retry_allowed'=>false,'attempts'=>[],'outboxes'=>[]];$attempts=[];
    foreach(['producer','reviewer'] as $role){
        if(isset($cache['attempts'][$role])){$x=$cache['attempts'][$role];$a=$x['row'];$box=$cache['outboxes'][$role];}
        else{
            $a=hotelOne($pdo,'SELECT attempt_id,campaign_id,stage_index,role,principal,state,baseline_sha256,request_sha256,request_bytes,result_sha256,result_bytes FROM hotel_server_attempts WHERE campaign_id=? AND stage_index=0 AND role=?',[HOTEL_CAMPAIGN,$role]);
            $box=hotelOne($pdo,'SELECT state,attempt_id FROM hotel_server_outbox WHERE campaign_id=? AND stage_index=0 AND role=?',[HOTEL_CAMPAIGN,$role]);
            if($a===null){if(isset($seen[$role]))hotelFail('original_startup_attempt_disappeared');
                if($box!==null&&($box['state']!=='pending'||$box['attempt_id']!==null))hotelFail('startup_pending_outbox_unconfirmed');$out['outboxes'][$role]=$box;continue;}
            $x=hotelObservedAttempt($a,$role,$plan,$policy,$inputs,$seed,$criteria,$principals[$role],$seen);
            if($box===null||$box['attempt_id']!==$a['attempt_id']||$box['state']!==($a['state']==='unknown'?'unknown':'done'))hotelFail('startup_attempt_outbox_unconfirmed');
            // Core results and done outboxes are immutable; never reparse a succeeded role on each poll.
            if($x['result']!==null){$cache['attempts'][$role]=$x;$cache['outboxes'][$role]=$box;}
        }
        $out['outboxes'][$role]=$box;
        $attempts[$role]=$x;$out['attempts'][$role]=$x['proof'];if($x['proof']['provider_call_confirmed'])++$out['provider_calls_confirmed'];
    }
    if(!isset($attempts['producer'])){if(isset($attempts['reviewer']))hotelFail('startup_role_order_unconfirmed');return $out;}
    $producer=$attempts['producer'];
    if($producer['result']===null){if(isset($attempts['reviewer']))hotelFail('startup_role_order_unconfirmed');$out['state']='original_producer_unknown';return $out;}
    if(isset($producer['result']['provider_outcome'])){$out['state']='producer_rejected';$out['reason']=$producer['result']['rejection_code'];return $out;}
    if(isset($cache['candidate'])){[$candidate,$candidateBytes,$document,$keys]=$cache['candidate'];}
    else{
        $candidate=hotelOne($pdo,'SELECT candidate_sha256,producer_attempt,candidate_bytes FROM hotel_server_candidates WHERE campaign_id=? AND stage_index=0',[HOTEL_CAMPAIGN]);
        if($candidate===null||$candidate['producer_attempt']!==$producer['row']['attempt_id'])hotelFail('startup_candidate_not_saved');
        $candidateBytes=hotelCheckedBytes($candidate,'candidate_bytes','candidate_sha256',1048576);$document=hotelJson($candidateBytes);
        if(HotelServerInputs::json($producer['result']['candidate']??null)!==$candidateBytes||($document['schema']??null)!=='hotel-server-candidate-v1'
            ||!is_array($document['records']??null)||!array_is_list($document['records']))hotelFail('startup_candidate_lineage_unconfirmed');
        $keys=[];foreach($document['records'] as $r)$keys[]=HotelServerInputs::key($r['scope']??[]);sort($keys);
        $wanted=array_map([HotelServerInputs::class,'key'],$plan['stages'][0]);sort($wanted);if($keys!==$wanted||count(array_unique($keys))!==4)hotelFail('startup_candidate_scope_unconfirmed');
        $cache['candidate']=[$candidate,$candidateBytes,$document,$keys];
    }
    $out['candidate_sha256']=$candidate['candidate_sha256'];$out['candidate_record_count']=count($keys);$out['state']='producer_saved_reviewer_pending';
    if(!isset($attempts['reviewer']))return $out;
    $reviewer=$attempts['reviewer'];
    if($reviewer['row']['attempt_id']===$producer['row']['attempt_id']||$reviewer['row']['principal']===$producer['row']['principal']
        ||($reviewer['request']['candidate_sha256']??null)!==$candidate['candidate_sha256']
        ||HotelServerInputs::json($reviewer['request']['candidate']??null)!==$candidateBytes)hotelFail('startup_independent_review_unconfirmed');
    if($reviewer['result']===null){$out['state']='original_reviewer_unknown';return $out;}
    if($reviewer['result']['provider_response_id']===$producer['result']['provider_response_id'])hotelFail('startup_distinct_provider_invocations_required');
    if(isset($reviewer['result']['provider_outcome'])){$out['state']='reviewer_rejected';$out['reason']=$reviewer['result']['rejection_code'];return $out;}
    $review=hotelOne($pdo,'SELECT review_attempt,candidate_sha256,approved,review_bytes FROM hotel_server_reviews WHERE campaign_id=? AND stage_index=0',[HOTEL_CAMPAIGN]);
    if($review===null||$review['review_attempt']!==$reviewer['row']['attempt_id']||$review['candidate_sha256']!==$candidate['candidate_sha256']
        ||$review['review_bytes']!==$reviewer['row']['result_bytes']||!is_bool($reviewer['result']['approved']??null)
        ||(int)$review['approved']!==($reviewer['result']['approved']?1:0)||($reviewer['result']['candidate_sha256']??null)!==$candidate['candidate_sha256']
        ||($reviewer['result']['criteria_sha256']??null)!==$criteria)hotelFail('startup_saved_review_unconfirmed');
    if($reviewer['result']['approved']!==true){$out['state']='independent_review_declined';return $out;}
    $out['state']='approved_review_awaiting_acceptance';
    $receiptRow=hotelOne($pdo,'SELECT receipt_sha256,receipt_bytes FROM hotel_server_receipts WHERE campaign_id=? AND stage_index=0',[HOTEL_CAMPAIGN]);
    if($receiptRow===null){if((int)$c['new_accepted']>0)hotelFail('startup_acceptance_receipt_missing');return $out;}
    $receiptBytes=hotelCheckedBytes($receiptRow,'receipt_bytes','receipt_sha256',65536);$receipt=hotelJson($receiptBytes);
    $newBaseline=hotelHash((string)($receipt['baseline_sha256']??''));
    $expectedReceipt=['schema'=>'hotel-server-acceptance-v1','campaign_id'=>HOTEL_CAMPAIGN,'stage_index'=>0,'candidate_sha256'=>$candidate['candidate_sha256'],
        'producer_attempt'=>$producer['row']['attempt_id'],'review_attempt'=>$reviewer['row']['attempt_id'],'previous_baseline_sha256'=>$seed,
        'baseline_sha256'=>$newBaseline,'inputs_sha256'=>$inputs,'new_acceptance_credit'=>1,'historical_accepted'=>19,'retained_admission'=>$admission];
    if(HotelServerInputs::json($expectedReceipt)!==$receiptBytes||(int)$c['new_accepted']<1||(int)$c['stage_cursor']<1||$newBaseline===$seed)hotelFail('startup_acceptance_lineage_unconfirmed');
    foreach($document['records'] as $record){$key=HotelServerInputs::key($record['scope']);
        $saved=hotelOne($pdo,'SELECT campaign_id,candidate_sha256,record_bytes FROM hotel_server_records WHERE semantic_key=?',[$key]);
        if($saved===null||$saved['campaign_id']!==HOTEL_CAMPAIGN||$saved['candidate_sha256']!==$candidate['candidate_sha256']||$saved['record_bytes']!==HotelServerInputs::json($record))hotelFail('startup_accepted_record_not_saved');}
    $baseline=hotelOne($pdo,'SELECT parent_sha256,document_bytes FROM hotel_server_baselines WHERE campaign_id=? AND baseline_sha256=?',[HOTEL_CAMPAIGN,$newBaseline]);
    $delta=HotelServerInputs::json(['schema'=>'hotel-server-baseline-v1','parent_sha256'=>$seed,'candidate_sha256'=>$candidate['candidate_sha256'],'records'=>$document['records']]);
    if($baseline===null||$baseline['parent_sha256']!==$seed||$baseline['document_bytes']!==$delta||hash('sha256',$delta)!==$newBaseline)hotelFail('startup_accepted_baseline_not_saved');
    $out['state']='first_acceptance_confirmed';$out['first_new_acceptance_confirmed']=true;$out['receipt_sha256']=$receiptRow['receipt_sha256'];
    $out['receipt']=$receipt;$out['saved_record_count']=count($document['records']);$out['saved_records']=$document['records'];
    $next=hotelOne($pdo,'SELECT stage_index,role,state,attempt_id FROM hotel_server_outbox WHERE campaign_id=? AND stage_index=1 AND role=?',[HOTEL_CAMPAIGN,'producer']);
    if($next===null||!in_array($next['state'],['pending','unknown','done'],true)
        ||($next['state']==='pending'?$next['attempt_id']!==null:!is_string($next['attempt_id'])))hotelFail('startup_next_producer_outbox_unconfirmed');
    if($next['attempt_id']!==null)hotelHash($next['attempt_id']);$out['next_stage_producer_outbox']=$next;
    $out['next_stage_provider_call_claimed']=false;return $out;
}
function hotelObserveStartup(PDO $pdo,array $plan,array $policy,string $inputs,string $seed,string $bootstrap,string $criteria,array $principals,array $admission): array {
    $started=hrtime(true);$until=$started+HOTEL_START_OBSERVE_SECONDS*1000000000;$seen=[];$cache=[];$snapshots=0;
    $last=['state'=>'observation_not_started','provider_calls_confirmed'=>0,'first_new_acceptance_confirmed'=>false,'automatic_retry_allowed'=>false];
    try{
        do{
            if($pdo->inTransaction())hotelFail('startup_foreign_transaction');
            $pdo->exec('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ');$pdo->exec('START TRANSACTION WITH CONSISTENT SNAPSHOT, READ ONLY');
            try{if(!$pdo->inTransaction())hotelFail('startup_read_only_snapshot_unconfirmed');
                $last=hotelStartupSnapshot($pdo,$plan,$policy,$inputs,$seed,$bootstrap,$criteria,$principals,$admission,$seen,$cache);++$snapshots;
            }finally{if($pdo->inTransaction())$pdo->rollBack();}
            if($last['first_new_acceptance_confirmed']||in_array($last['state'],['producer_rejected','reviewer_rejected','independent_review_declined'],true)||($last['campaign_state']??null)==='hold')break;
            $left=$until-hrtime(true);if($left<=0)break;
            usleep((int)min(5000000,intdiv($left,1000)));
        }while(hrtime(true)<$until);
        $last['observation_deadline_reached']=hrtime(true)>=$until&&!$last['first_new_acceptance_confirmed'];
